   status.textContent=proposal.status==='ANCHOR_REVIEW'?tx('al.28','Gelernte Textanker: neue Werte aus diesem Dokument gelesen. Bitte prüfen.'):tx('al.29','Bestätigtes Muster mit identischem Text gefunden. Bitte prüfen.');
