$('#submitImport').onclick=async()=>{const valid=swiftItems.filter(x=>x.preview?.valid);$('#submitImport').disabled=true;const results=[];for(const item of valid){const box=document.querySelector(`[data-swift-index="${swiftItems.indexOf(item)}"] [data-party-correction]`);const party=box&&globalThis.LcPartyReference?LcPartyReference.read(box):null;if(party?.missing.length){results.push({...item,success:false,error:`Bitte ${party.missing.join(tx('al.70',' und '))} ergänzen (die Nachricht verweist nur auf ein anderes Feld).`});continue}try{await json('/api/imports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...item,applicant:party?.applicant||null,beneficiary:party?.beneficiary||null})});results.push({...item,success:true})}catch(e){results.push({...item,success:false,error:e.message})}}const success=results.filter(x=>x.success).length;$('#preview').innerHTML=`<h3>${tx('ai.a22c68','Import abgeschlossen:')} ${success} erfolgreich, ${results.length-success} fehlgeschlagen</h3><div class="batch-list">${results.map(x=>`<div class="batch-row ${x.success?'ready':'invalid'}"><span class="batch-icon">${x.success?'✓':'×'}</span><div><b>${esc(x.filename)}</b><small>${x.success?'Import erfolgreich':esc(x.error)}</small></div></div>`).join('')}</div>`;$('#submitImport').textContent='Import abgeschlossen';await load()};
