async function deleteTraining(button){if(!await confirmAction(tx('at.8388d7','Trainingsvorlage „{p0}“ ausblenden? Die Lerninhalte bleiben erhalten.',{p0:button.dataset.trainingName})))return;button.disabled=true;try{await json(`/api/training/${button.dataset.trainingDelete}`,{method:'DELETE'});if(trainingItem?.sessionId===button.dataset.trainingDelete){trainingItem=null;$('#trainingDialog').close()}await Promise.all([loadTrainingHistory(),loadDashboardDrafts()])}catch(e){$('#trainingError').textContent=tx('inbox.deleteFailed','Löschen fehlgeschlagen: ')+e.message;button.disabled=false}}
async function deleteSelectedTraining(){const ids=[...document.querySelectorAll('.training-select:checked')].map(x=>x.value);if(!ids.length){alert(tx('al.104','Bitte zuerst Trainingsvorlagen auswählen.'));return}if(!await confirmAction(tx('at.0c3081','{p0} Trainingsvorlage(n) ausblenden? Die Lerninhalte bleiben erhalten.',{p0:ids.length})))return;try{await json('/api/training/templates',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify(ids)});await Promise.all([loadTrainingHistory(),loadDashboardDrafts()])}catch(e){$('#trainingError').textContent=tx('inbox.deleteFailed','Löschen fehlgeschlagen: ')+e.message}}
async function openTrainingSession(id){try{const item=await json(`/api/training/${id}`);trainingItem={sessionId:item.id,extractionStatus:item.extractionStatus,preview:{messageType:item.messageType,rawFields:item.fields||[],valid:false,errors:[]},reviews:(item.fields||[]).map(x=>x.review||'correct')};$('#trainingDrop').classList.add('hidden');renderTraining();document.querySelectorAll('.training-field textarea').forEach(x=>x.readOnly=true);document.querySelectorAll('.review-actions').forEach(x=>x.classList.add('hidden'));$('#confirmTraining').classList.add('hidden');$('#trainingReviewProgress').textContent=`${item.status==='CONFIRMED'?tx('al.105','Bestätigter Datensatz'):'Entwurf'} · ${esc(item.filename)}`}catch(e){$('#trainingError').textContent=e.message}}
async function loadTrainingQuality(){try{const rows=await json('/api/training/quality');$('#trainingQuality').innerHTML=rows.length?`<details><summary>${tx('ah.7d5958','OCR-Qualität nach Profil und Feld')}</summary><div class="quality-profiles">${rows.map(p=>`<section><h4>${esc(p.messageType)} <span>${p.accuracyPercent}% unverändert erkannt</span></h4><small>${p.sessions} bestätigte Dokumente · ${p.fields} geprüfte Felder · ${p.corrected} korrigiert</small><div class="quality-fields">${p.fieldQuality.map(f=>`<span>:${esc(f.code)}: <b>${f.accuracyPercent}%</b><small>${tx('b4.checkedN','{n}× geprüft',{n:f.confirmed})}</small></span>`).join('')}</div></section>`).join('')}</div></details>`:'<small>'+tx('ah.917dec','Noch nicht genügend bestätigte Daten für die Qualitätsanzeige.')+'</small>'}catch(e){$('#trainingQuality').innerHTML=''}}
async function loadLearningRules(){try{const rules=await json('/api/training/learning-rules');$('#learningHistory').innerHTML=rules.length?`<details><summary>${tx('ai.b42df8','Lernhistorie (')}${rules.length} Regeln)</summary><div class="learning-rules">${rules.map(rule=>`<section class="learning-rule ${rule.active?'':'inactive'}"><div><b>${esc(rule.messageType)} · ${esc(rule.kind)}</b><small>:${esc(rule.sourceCode)}:${rule.sourceValue?` „${esc(rule.sourceValue)}“`:''} → ${rule.rejected?'nicht verwenden':`:${esc(rule.targetCode)}:${rule.targetValue?` „${esc(rule.targetValue)}“`:''}`}</small><small>${rule.examples}× gelernt · ${rule.documents.map(esc).join(', ')}</small></div><button type="button" class="secondary learning-toggle" data-id="${rule.id}" data-active="${rule.active}">${rule.active?'Deaktivieren':'Aktivieren'}</button></section>`).join('')}</div></details>`:'<small>'+tx('ah.37f2a1','Noch keine dauerhaften Lernregeln vorhanden.')+'</small>';document.querySelectorAll('.learning-toggle').forEach(button=>button.onclick=()=>toggleLearningRule(button))}catch(e){$('#learningHistory').innerHTML='<small>'+tx('ah.398f7b','Lernhistorie konnte nicht geladen werden.')+'</small>'}}
