function swiftFieldOptions(type,current){const codes=[...new Set([current,...(swiftCatalog[type]||swiftCatalog.MT700)])];return codes.map(code=>`<option value="${esc(code)}" ${code===current?'selected':''}>:${esc(code)}:</option>`).join('')}
function reassignTrainingField(index){const row=document.querySelector(`.training-field[data-index="${index}"]`),select=row.querySelector('.swift-code-select'),field=trainingItem.preview.rawFields[index];row.querySelector('.training-field-head b').textContent=`SWIFT-Feld :${select.value}:`;row.querySelector('.field-reassignment small').textContent=select.value===field.code?tx('al.114','Ursprüngliche Zuordnung'):tx('al.115','Ursprünglich als :')+field.code+': erkannt';setTrainingReview(index,select.value===field.code?'correct':'reassigned')}
async function loadTrainingSnippets(){for(const img of document.querySelectorAll('.snippet-frame img')){const frame=img.parentElement;try{const response=await fetch(img.dataset.src,{credentials:'same-origin'});if(!response.ok)throw new Error(`HTTP ${response.status}`);const blob=await response.blob();if(!blob.size)throw new Error('Leere Bildantwort');const url=URL.createObjectURL(blob);img.onload=()=>{frame.classList.add('loaded')};img.onerror=()=>{frame.classList.add('failed');frame.querySelector('span').textContent=tx('al.116','PDF-Ausschnitt ist kein gültiges Bild');URL.revokeObjectURL(url)};img.src=url}catch(error){frame.classList.add('failed');frame.querySelector('span').textContent=tx('at.0ee13c','PDF-Ausschnitt konnte nicht geladen werden ({p0})',{p0:error.message})}}}
