function openOriginalPdf(){if(!trainingItem?.sessionId)return;const url=`/api/training/${trainingItem.sessionId}/document`;let dialog=$('#originalPdfDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='originalPdfDialog';dialog.className='original-pdf-dialog';dialog.innerHTML='<div class="dialoghead"><div><h2>'+tx('ai.3ca488','Original-PDF')+'</h2><p>'+tx('ah.6c7828','Vollständiges Dokument zur fachlichen Prüfung.')+'</p></div><button type="button" class="ghost close-original">×</button></div><iframe title="'+tx('ah.9fcf27','Vollständiges Original-PDF')+'"></iframe><div class="actions"><a class="button-link" target="_blank" rel="noopener">'+tx('ah.29c9ec','In eigenem Tab öffnen')+'</a><button type="button" class="secondary close-original">'+tx('ah.8311b9','Schließen')+'</button></div>';document.body.append(dialog);dialog.querySelectorAll('.close-original').forEach(button=>button.onclick=()=>dialog.close())}dialog.querySelector('iframe').src=url;dialog.querySelector('a').href=url;dialog.showModal()}
function renderTraining(){const p=trainingItem.preview,fields=p.rawFields||[],unclear=fields.filter(x=>x.confidence!=='HIGH'||x.ocr?.status==='REVIEW'||x.ocr?.status==='UNAVAILABLE').length;$('#confirmTraining').textContent=p.messageType==='MT700'?tx('al.117','Bestätigen & LC anlegen'):p.messageType==='MT707'?tx('al.118','Bestätigen & Amendment übernehmen'):tx('al.119','Bestätigen & Trainingsdaten speichern');$('#trainingStatus').innerHTML=`<div class="training-summary"><b>${esc(p.messageType||'Format unbekannt')}</b><span>${fields.length} Felder</span><span>${unclear} automatisch unsicher</span><span>${trainingItem.extractionStatus==='OCR_EXTRACTED'?'OCR verwendet':'Textschicht erkannt'}</span><strong id="trainingReviewProgress"></strong></div><div id="trainingGate" class="training-gate"><span>${tx('ah.7842cd','Qualitätsprüfung wird vorbereitet …')}</span></div>`;$('#trainingFields').innerHTML=fields.map((f,index)=>`<div class="training-field ${f.unusual?'unusual':''}" data-index="${index}"><div class="training-field-head"><b>${tx('ai.16a55f','SWIFT-Feld :')}${esc(f.code)}:</b><span>${esc(f.label)}</span><label class="field-reassignment">${tx('ai.4caec6','Anderem SWIFT-Feld zuordnen')}<select class="swift-code-select">${swiftFieldOptions(p.messageType,f.code)}</select><small>${tx('ah.cc7f51','Ursprüngliche Zuordnung')}</small></label></div><div class="pdf-context"><small>${tx('ah.53d182','Original im PDF')}</small><div class="snippet-frame"><span>${tx('ah.399f17','PDF-Ausschnitt wird vorbereitet …')}</span><img data-src="/api/training/${trainingItem.sessionId}/snippet/${index}?v=5" alt="${tx('b4.snippetAlt','PDF-Ausschnitt für Feld {code}',{code:esc(f.code)})}"><button type="button" class="snippet-zoom">${tx('ah.4d473b','⌕ Vergrößern')}</button></div></div><div class="training-value"><small>${tx('ai.c2a0a0','Erkannter Feldinhalt')}</small><textarea maxlength="12000">${esc(f.value)}</textarea><div class="review-actions"><button type="button" class="secondary" data-review="correct">${tx('ai.479cbb','✓ Richtig erkannt')}</button><button type="button" class="secondary" data-review="corrected">${tx('ah.59d00c','✎ Korrektur bestätigen')}</button><button type="button" class="reject-review" data-review="invalid">${tx('ah.168033','× Nicht verwendbar')}</button></div></div><div class="training-target"><small>${tx('ah.099992','Zuordnung im LC-Manager')}</small><span class="confidence ${String(f.confidence).toLowerCase()}">${f.confidence==='HIGH'?'Automatisch sicher':tx('al.120','Automatisch prüfen')}</span><b>${esc(f.targetLabel)}</b>${renderOcrConfidence(f.ocr)}${f.confidenceScore!=null?`<small>${tx('ai.a938ba','Zuordnungsbewertung:')} ${Math.round(f.confidenceScore*100)} % · ${tx('b4.heuristic','heuristisch, keine OCR-Messung')}</small>`:''}${f.notice?`<small class="placement-warning">${esc(f.notice)}</small>`:''}</div></div>`).join('');loadTrainingSnippets();document.querySelectorAll('.training-field').forEach(row=>{const index=Number(row.dataset.index);row.querySelectorAll('.review-actions button').forEach(button=>button.onclick=()=>setTrainingReview(index,button.dataset.review));row.querySelector('.swift-code-select').onchange=()=>reassignTrainingField(index);row.querySelector('.snippet-zoom').onclick=()=>{const img=row.querySelector('.snippet-frame img');if(img.src)openSnippetZoom(img)};row.querySelector('.snippet-frame img').onclick=event=>openSnippetZoom(event.currentTarget);row.querySelector('textarea').oninput=()=>{trainingItem.reviews[index]=null;$('#trainingError').textContent='';row.classList.remove('review-correct','review-corrected','review-reassigned','review-invalid');row.querySelectorAll('.review-actions button').forEach(button=>button.classList.remove('selected'));updateTrainingReview()}});updateTrainingReview();$('#trainingError').textContent=p.errors?.join(' ')||''}
async function confirmTraining(){const open=trainingItem.reviews.map((status,index)=>status?null:trainingItem.preview.rawFields[index]?.code||String(index+1)).filter(Boolean);if(open.length){$('#trainingError').textContent=tx('at.0c13fd','Noch nicht fachlich bestätigt: {p0}. Bitte diese Felder bestätigen, neu zuordnen oder als nicht verwendbar markieren.',{p0:open.map(code=>':'+code+':').join(', ')});const first=document.querySelector(`.training-field[data-index="${trainingItem.reviews.findIndex(status=>!status)}"]`);first?.scrollIntoView({behavior:'smooth',block:'center'});return}const fields=trainingItem.preview.rawFields.map((field,index)=>{const row=document.querySelector(`.training-field[data-index="${index}"]`);return {...field,originalCode:field.code,code:row.querySelector('.swift-code-select').value,value:row.querySelector('textarea').value.trim(),review:trainingItem.reviews[index]}});const raw=fields.filter(f=>f.review!=='invalid').map(f=>`:${f.code}:${f.value}`).join('\n');$('#confirmTraining').disabled=true;$('#trainingError').textContent='';try{await json(`/api/training/${trainingItem.sessionId}/confirm`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({correctedRawMessage:raw,reviewsJson:JSON.stringify(fields)})});$('#trainingDialog').close();await load()}catch(e){$('#trainingError').textContent=e.message;$('#confirmTraining').disabled=false}}
let tlsStatus=null;
async function loadTlsStatus(){const button=$('#tlsStatusBtn');try{tlsStatus=await json('/api/security/tls-status');button.className=`tls-status tls-${tlsStatus.status.toLowerCase()}`;button.querySelector('.tls-copy b').textContent=tlsStatus.label;button.querySelector('.tls-copy small').textContent=tlsStatus.message}catch(e){tlsStatus={status:'YELLOW',label:tx('al.122','Prüfung nicht möglich'),message:tx('al.123','Der Verbindungsstatus konnte nicht geladen werden.'),encrypted:location.protocol==='https:',scheme:location.protocol.replace(':',''),host:location.host,proxyIndicators:[],limitation:'Die Ampel konnte keine Serverprüfung durchführen.'};button.className='tls-status tls-yellow';button.querySelector('.tls-copy b').textContent=tlsStatus.label;button.querySelector('.tls-copy small').textContent=tlsStatus.message}}
function showTlsDetails(){if(!tlsStatus)return;const color={GREEN:tx('al.124','Grün'),YELLOW:'Gelb',RED:'Rot'}[tlsStatus.status]||tlsStatus.status;$('#tlsDetails').innerHTML=`<div class="tls-result tls-${String(tlsStatus.status).toLowerCase()}"><span class="traffic-light large"><i class="red"></i><i class="yellow"></i><i class="green"></i></span><div><h3>${esc(color)} – ${esc(tlsStatus.label)}</h3><p>${esc(tlsStatus.message)}</p></div></div><dl><dt>${tx('ai.ea1a00','Verbindung')}</dt><dd>${tlsStatus.encrypted?tx('mo.https','HTTPS / verschlüsselt'):tx('b4.notHttps','nicht als HTTPS erkannt')}</dd><dt>${tx('ai.50d46c','Adresse')}</dt><dd>${esc(tlsStatus.host||location.host)}</dd><dt>${tx('ai.c86cb0','Sichtbare Indikatoren')}</dt><dd>${tlsStatus.proxyIndicators?.length?tlsStatus.proxyIndicators.map(esc).join(', '):tx('al.125','Keine typischen Proxy-/Inspection-Header erkannt')}</dd></dl><p class="tls-limitation"><b>${tx('ai.a0a61a','Wichtig:')}</b> ${esc(tlsStatus.limitation)}</p>`;$('#tlsDialog').showModal()}
$('#tlsStatusBtn').onclick=showTlsDetails;$('#closeTls').onclick=$('#closeTlsAction').onclick=()=>$('#tlsDialog').close();
