let trainingSaveTimer=null,trainingQualityTimer=null;
function trainingDraftPayload(){const fields=trainingItem.preview.rawFields.map((field,index)=>{const row=document.querySelector(`.training-field[data-index="${index}"]`);return {...field,originalCode:field.originalCode||field.code,code:row?.querySelector('.swift-code-select')?.value||field.code,value:row?.querySelector('textarea')?.value.trim()??field.value,review:trainingItem.reviews[index]}});return {correctedRawMessage:fields.filter(field=>field.review!=='invalid').map(field=>`:${field.code}:${field.value}`).join('\n'),reviewsJson:JSON.stringify(fields)}}
function scheduleTrainingSave(){if(!trainingItem?.sessionId||trainingItem.status==='CONFIRMED')return;clearTimeout(trainingSaveTimer);clearTimeout(trainingQualityTimer);let state=$('#trainingAutosave');if(!state){state=document.createElement('small');state.id='trainingAutosave';state.className='training-autosave';$('#trainingReviewProgress').after(state)}state.textContent=tx('al.126','Änderung wird gespeichert …');trainingSaveTimer=setTimeout(saveTrainingDraft,500);trainingQualityTimer=setTimeout(validateTrainingQuality,750)}
async function validateTrainingQuality(){if(!trainingItem?.sessionId||trainingItem.status==='CONFIRMED'||!$('#trainingGate'))return;try{const result=await json(`/api/training/${trainingItem.sessionId}/validate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(trainingDraftPayload())}),labels={GREEN:tx('al.127','Grün – fachlich plausibel'),YELLOW:tx('al.128','Gelb – Hinweise prüfen'),RED:tx('al.129','Rot – Abschluss nicht möglich')},items=[...result.blockers,...result.warnings,...result.information];$('#trainingGate').className=`training-gate gate-${result.status.toLowerCase()}`;$('#trainingGate').innerHTML=`<span class="traffic-light tls-${result.status.toLowerCase()}"><i class="red"></i><i class="yellow"></i><i class="green"></i></span><div><b>${labels[result.status]}</b>${items.length?`<ul>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:'<small>'+tx('ah.65d91d','Keine Auffälligkeiten gefunden.')+'</small>'}</div>`}catch(e){$('#trainingGate').className='training-gate gate-yellow';$('#trainingGate').textContent=tx('al.130','Qualitätsprüfung derzeit nicht möglich: ')+e.message}}
