openTrainingSession=async function(id){try{const item=await json(`/api/training/${id}`),editable=item.status!=='CONFIRMED';trainingItem={sessionId:item.id,status:item.status,extractionStatus:item.extractionStatus,preview:{messageType:item.messageType,rawFields:item.fields||[],valid:editable,errors:[]},reviews:(item.fields||[]).map(field=>field.review||null)};$('#trainingDrop').classList.add('hidden');$('#confirmTraining').classList.toggle('hidden',!editable);renderTraining();if(!editable){document.querySelectorAll('.training-field textarea,.training-field select').forEach(control=>control.disabled=true);document.querySelectorAll('.review-actions').forEach(actions=>actions.classList.add('hidden'))}$('#trainingReviewProgress').textContent=`${editable?'Bearbeitbarer Entwurf':tx('al.105','Bestätigter Datensatz')} · ${esc(item.filename)}`}catch(e){$('#trainingError').textContent=e.message}};
