function ensureDocumentCreationUi(){if($('#generateDocumentDialog'))return;const dialog=document.createElement('dialog');dialog.id='generateDocumentDialog';dialog.innerHTML=`<form id="generateDocumentForm"><div class="dialoghead"><div><h2 id="generateDocumentTitle">${tx('gf.title','Dokument erstellen')}</h2><p>${tx('gf.intro','LC-Daten werden automatisch übernommen.')}</p></div><button type="button" class="ghost generate-close">×</button></div><input type="hidden" name="type"><div class="form-grid"><label>${tx('gf.number','Dokumentnummer')}<input name="documentNumber" required maxlength="100"></label><label>${tx('ds.documentDate','Dokumentdatum')}<input name="documentDate" type="date" required></label><label class="wide">${tx('lc.goods','Warenbeschreibung')}<textarea name="description" class="compact-textarea" maxlength="4000"></textarea></label><label>${tx('ds.field.quantity','Menge')}<input name="quantity" maxlength="100" placeholder="${tx('gf.qtyHint','z. B. 100 Stück')}"></label><label>${tx('ds.field.packages','Packstücke')}<input name="packages" type="number" min="0"></label><label>${tx('gf.net','Nettogewicht (kg)')}<input name="netWeight" type="number" min="0" step="0.001"></label><label>${tx('gf.gross','Bruttogewicht (kg)')}<input name="grossWeight" type="number" min="0" step="0.001"></label><label class="wide">${tx('ds.notes','Hinweise')}<textarea name="notes" class="compact-textarea" maxlength="4000"></textarea></label></div><div id="generateDocumentError" class="error"></div><div class="actions"><button type="button" class="secondary generate-close">${tx('gf.cancel','Abbrechen')}</button><button type="button" id="generateDocx" class="secondary">${tx('gf.word','Word erstellen')}</button><button type="submit">${tx('gf.pdf','PDF erstellen')}</button></div></form>`;document.body.append(dialog);dialog.querySelectorAll('.generate-close').forEach(button=>button.onclick=()=>dialog.close());const values=()=>{const result=Object.fromEntries(new FormData($('#generateDocumentForm')).entries());for(const key of ['packages','netWeight','grossWeight'])result[key]=result[key]===''?null:Number(result[key]);return result};const create=async format=>{if(!$('#generateDocumentForm').reportValidity())return;try{await json(`/api/lcs/${activeLc.id}/generated-documents${format==='docx'?'/docx':''}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values())});dialog.close();await showKeepingView(activeLc.id)}catch(e){$('#generateDocumentError').textContent=e.message}};$('#generateDocumentForm').onsubmit=async event=>{event.preventDefault();await create('pdf')};$('#generateDocx').onclick=()=>create('docx')}
