function addDocumentItem(){const list=$('#documentItemList'),index=list.children.length+1;list.insertAdjacentHTML('beforeend',documentItemRow(index));list.lastElementChild.querySelector('.item-remove').onclick=event=>{event.currentTarget.closest('.document-item-row').remove();[...list.children].forEach((row,i)=>row.querySelector('[name="itemPosition"]').value=i+1)}}
