function appendTaskQueue(){if(!openTasks.length)return;const overdue=openTasks.filter(task=>daysUntil(task.dueDate)<0).length,upcoming=openTasks.filter(task=>{const days=daysUntil(task.dueDate);return days>=0&&days<=7}).length;$('#queueOverdue').textContent=Number($('#queueOverdue').textContent)+overdue;$('#queueUpcoming').textContent=Number($('#queueUpcoming').textContent)+upcoming;const rows=openTasks.slice(0,8).map(task=>{const lc=data.find(item=>item.id===task.letterOfCreditId),days=daysUntil(task.dueDate),level=days<0?'overdue':days<=7?'urgent':'normal';return `<div class="queue-row task-queue-row" data-queue-id="${task.letterOfCreditId}"><span class="queue-priority ${level}"></span><div><b>${esc(lc?.reference||'LC-Akte')}</b><small>${tx('ai.8c5713','Aufgabe')}</small></div><div><span class="deadline ${level}">${esc(task.title)}</span><small>${task.dueDate?tx('al.139','Fällig ')+esc(fmtDate(task.dueDate)):tx('al.140','Keine Fälligkeit')}</small></div><div><b>${esc(task.assignedTo||tx('al.133','Nicht zugewiesen'))}</b><small>${tx('ai.ddf363','Bearbeiter')}</small></div><button type="button" class="secondary">${tx('ah.9a99db','Akte öffnen')}</button></div>`}).join('');$('#workQueueList').insertAdjacentHTML('afterbegin',rows);document.querySelectorAll('.task-queue-row').forEach(row=>row.onclick=async()=>{await show(row.dataset.queueId);activateDossierSection('tasks')})}
