function setupDocumentBatchUpload(){const form=$('#uploadForm'),input=form?.elements.file;if(!form||!input)return;auditLabels.DOCUMENT_BATCH_UPLOADED='Dokumenten-Batch hochgeladen';input.multiple=true;input.closest('label').firstChild.textContent='Dateien oder ZIP-Archive';[...form.querySelectorAll('.form-grid>label')].slice(1).forEach(label=>label.classList.add('hidden'));const preview=document.createElement('div');preview.id='documentBatchPreview';preview.className='document-batch-preview hidden';$('#uploadError').before(preview);const types=[['COMMERCIAL_INVOICE','Handelsrechnung'],['PACKING_LIST','Packliste'],['BILL_OF_LADING','Konnossement'],['AIR_WAYBILL','Luftfrachtbrief'],['ROAD_CONSIGNMENT_NOTE','CMR'],['CERTIFICATE_OF_ORIGIN','Ursprungszeugnis'],['INSURANCE_CERTIFICATE','Versicherungszertifikat'],['INSPECTION_CERTIFICATE','Inspektionszertifikat'],['BILL_OF_EXCHANGE','Wechsel'],['BENEFICIARY_CERTIFICATE',tx('al.0','Begünstigtenzertifikat')],['QUALITY_CERTIFICATE',tx('al.1','Qualitätszertifikat')],['COURIER_RECEIPT','Kurierbeleg'],['ADVISING_LETTER','Avisierungsschreiben'],['SWIFT_MT700',tx('al.2','SWIFT MT700 / Akkreditiveröffnung')],['ANNEX','Anlage'],['SEA_WAYBILL','Sea Waybill'],['CHARTER_PARTY_BILL_OF_LADING','Charter Party Bill of Lading'],['MULTIMODAL_TRANSPORT_DOCUMENT','Multimodal Transport Document'],['WEIGHT_LIST','Weight List'],['POST_RECEIPT','Post Receipt'],['OTHER','Sonstiges']];const suggest=name=>{name=name.toLowerCase();if(/invoice|rechnung/.test(name))return'COMMERCIAL_INVOICE';if(/packing|packliste/.test(name))return'PACKING_LIST';if(/bill.?of.?lading|(^|[-_ ])bl([-_ .]|$)/.test(name))return'BILL_OF_LADING';if(/airway|air-waybill|awb/.test(name))return'AIR_WAYBILL';if(/cmr/.test(name))return'ROAD_CONSIGNMENT_NOTE';if(/origin|ursprung/.test(name))return'CERTIFICATE_OF_ORIGIN';if(/insurance|versicherung/.test(name))return'INSURANCE_CERTIFICATE';if(/inspection|inspektion/.test(name))return'INSPECTION_CERTIFICATE';if(/draft|bill.?of.?exchange|wechsel/.test(name))return'BILL_OF_EXCHANGE';if(/beneficiary.?certificate/.test(name))return'BENEFICIARY_CERTIFICATE';if(/quality|analysis|analyse/.test(name))return'QUALITY_CERTIFICATE';if(/courier|dhl|fedex/.test(name))return'COURIER_RECEIPT';return'ANNEX'};input.onchange=()=>{const files=[...input.files];preview.classList.toggle('hidden',!files.length);preview.innerHTML=files.length?`<b>${files.length===1?tx('b4.src1','1 Quelldatei vor dem Upload prüfen'):tx('b4.srcN','{n} Quelldateien vor dem Upload prüfen',{n:files.length})}</b>${files.map((file,index)=>`<div class="document-batch-row"><div><strong>${esc(file.name)}</strong><small>${fileSize(file.size)}${file.name.toLowerCase().endsWith('.zip')?tx('al.143',' · Inhalt wird sicher entpackt und automatisch klassifiziert'):''}</small></div><select data-batch-type="${index}" ${file.name.toLowerCase().endsWith('.zip')?'disabled':''}>${types.map(([value,label])=>`<option value="${value}" ${value===suggest(file.name)?'selected':''}>${label}</option>`).join('')}</select><label>${tx('ai.10eff1','Kennzeichnung')}<select data-batch-copy="${index}" ${file.name.toLowerCase().endsWith('.zip')?'disabled':''}>${documentCopyOptions(null)}</select></label></div>`).join('')}`:''};form.addEventListener('reset',()=>setTimeout(()=>{preview.classList.add('hidden');preview.innerHTML=''},0));form.onsubmit=async event=>{event.preventDefault();if(!activeLc||!input.files.length)return;$('#uploadError').textContent='';const body=new FormData();[...input.files].forEach((file,index)=>{body.append('file',file);body.append('types',preview.querySelector(`[data-batch-type="${index}"]`)?.value||'ANNEX');body.append('copies',preview.querySelector(`[data-batch-copy="${index}"]`)?.value||'-99')});try{const imported=await json(`/api/lcs/${activeLc.id}/documents/batch`,{method:'POST',body});preview.innerHTML=`<div class="success-message"><b>${imported.length===1?tx('b4.imp1','1 Dokument erfolgreich übernommen.'):tx('b4.impN','{n} Dokumente erfolgreich übernommen.',{n:imported.length})}</b></div>${imported.map(document=>`<div class="document-batch-result"><span>✓</span><div><b>${esc(document.originalFilename)}</b><small>${esc(document.typeLabel)} · ${esc(document.extractionStatus)}</small></div></div>`).join('')}<div class="actions"><button type="button" id="finishBatchUpload">${tx('ah.d6b257','Zur Dokumentenakte')}</button></div>`;$('#finishBatchUpload').onclick=async()=>{$('#uploadDialog').close();await show(activeLc.id);activateDossierSection('documents')}}catch(e){$('#uploadError').textContent='Batch-Upload fehlgeschlagen: '+e.message}}}
function ensureApprovalPolicyUi(){if($('#appNavApprovalPolicy'))return;const button=document.createElement('button');button.id='appNavApprovalPolicy';button.type='button';button.textContent='Freigabestufen';button.className='hidden';$('#appNavTemplates').after(button);button.classList.remove('hidden');const dialog=document.createElement('dialog');dialog.id='approvalPolicyDialog';dialog.className='wide-dialog';dialog.innerHTML='<div class="dialoghead"><div><h2>'+tx('ai.094f70','Freigabestufen')+'</h2><p>'+tx('ah.139c0a','Je LC-Währung und Mindestbetrag lässt sich festlegen, wie viele verschiedene Freigeber benötigt werden. Ohne passende Regel genügt eine Freigabe.')+'</p></div><button type="button" class="ghost" data-approval-close>×</button></div><div id="approvalThresholdRows" class="approval-threshold-list"></div><div id="approvalPolicyError" class="error" role="alert"></div><div class="actions"><button type="button" id="addApprovalThreshold" class="secondary">'+tx('ah.8b5844','Betragsstufe hinzufügen')+'</button><button type="button" id="saveApprovalPolicy">'+tx('ah.b97d23','Speichern')+'</button></div>';document.body.append(dialog);dialog.querySelector('[data-approval-close]').onclick=()=>dialog.close();button.onclick=async()=>{dialog.showModal();$('#approvalPolicyError').textContent='';try{renderApprovalThresholds(await json('/api/settings/approval-thresholds'))}catch(e){$('#approvalPolicyError').textContent=e.message}};$('#addApprovalThreshold').onclick=()=>{const rules=readApprovalThresholds();rules.push({currency:'EUR',minimumAmount:'',requiredApprovals:2});renderApprovalThresholds(rules)};$('#saveApprovalPolicy').onclick=async()=>{try{const rules=readApprovalThresholds();if(rules.some(rule=>!rule.currency||rule.minimumAmount===''||!Number.isFinite(Number(rule.minimumAmount))))throw new Error('Bitte Währung und Mindestbetrag für jede Stufe vollständig angeben.');const saved=await json('/api/settings/approval-thresholds',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(rules.map(rule=>({...rule,requiredApprovals:Number(rule.requiredApprovals)})))});renderApprovalThresholds(saved);$('#approvalPolicyError').textContent='Freigabestufen gespeichert.'}catch(e){$('#approvalPolicyError').textContent=e.message}}}
function renderApprovalThresholds(rules){$('#approvalThresholdRows').innerHTML=rules.length?rules.map(rule=>`<div class="approval-threshold-row"><label>${tx('ah.f73cd5','Währung')}<input name="thresholdCurrency" value="${esc(rule.currency)}" maxlength="3" required placeholder="EUR"></label><label>${tx('ai.5d7cda','Mindestbetrag')}<input name="thresholdAmount" value="${rule.minimumAmount??''}" type="number" min="0" step="0.01" required></label><label>${tx('ai.149d1a','Freigeber')}<input name="thresholdApprovals" value="${rule.requiredApprovals}" type="number" min="1" max="5" required></label><button type="button" class="ghost danger-text" data-remove-approval>${tx('ai.513d30','Entfernen')}</button></div>`).join(''):'<div class="empty compact">'+tx('ah.aa5965','Noch keine Betragsstufen konfiguriert. Aktuell ist eine Freigabe erforderlich.')+'</div>';document.querySelectorAll('[data-remove-approval]').forEach(remove=>remove.onclick=()=>{remove.closest('.approval-threshold-row').remove();if(!$('#approvalThresholdRows').children.length)renderApprovalThresholds([])})}
function readApprovalThresholds(){return [...document.querySelectorAll('.approval-threshold-row')].map(row=>({currency:row.querySelector('[name="thresholdCurrency"]').value.trim().toUpperCase(),minimumAmount:row.querySelector('[name="thresholdAmount"]').value,requiredApprovals:row.querySelector('[name="thresholdApprovals"]').value}))}
function ensureRoleUi(){const dialog=document.createElement('dialog');dialog.id='rolesDialog';dialog.className='wide-dialog';dialog.innerHTML='<div class="dialoghead"><div><h2>'+tx('ai.2c1143','Rollen & Rechte')+'</h2><p>'+tx('ah.e91607','Benutzer erben alle Rechte ihrer zugewiesenen Rolle.')+'</p></div><button type="button" class="ghost role-close">×</button></div><div id="roleList" class="role-list"></div><form id="roleForm"><input type="hidden" name="id"><div class="form-grid"><label>'+tx('ai.112c6a','Rollenname')+'<input name="name" required maxlength="100"></label><label>'+tx('ai.ba3b00','Basistyp')+'<select name="baseRole"><option value="VIEWER">'+tx('ai.edf873','Leser')+'</option><option value="EDITOR">'+tx('ai.09a482','Sachbearbeiter')+'</option><option value="ADMIN">'+tx('ai.7b7bc2','Administrator')+'</option></select></label></div><div id="permissionList" class="permission-grid"></div><div id="roleError" class="error"></div><div class="actions"><button type="button" id="newRole" class="secondary">'+tx('ah.540ae0','Neue Rolle')+'</button><button type="submit">'+tx('ah.597317','Rolle speichern')+'</button></div></form>';document.body.append(dialog);dialog.querySelector('.role-close').onclick=()=>dialog.close();globalThis.openRolesEditor=async()=>{dialog.showModal();await loadRoles();resetRoleForm()};$('#newRole').onclick=resetRoleForm;$('#roleForm').onsubmit=saveRole;auditLabels.ROLE_CREATED='Rolle angelegt';auditLabels.ROLE_UPDATED='Rolle geändert';auditLabels.ROLE_DELETED='Rolle gelöscht';}
async function loadRoles(){[roles,permissionCatalog]=await Promise.all([json('/api/roles'),json('/api/roles/permissions')]);renderRoles()}
function renderRoles(){$('#roleList').innerHTML=roles.map(role=>`<div class="role-row" data-role-id="${role.id}"><div><b>${esc(role.name)}</b><small>${role.permissions.length} Rechte · ${role.systemRole?'Systemrolle':'Eigene Rolle'}</small></div>${role.systemRole?'':`<button type="button" class="danger" data-role-delete="${role.id}">${tx('ah.1010b0','Löschen')}</button>`}</div>`).join('');document.querySelectorAll('[data-role-id]').forEach(row=>row.onclick=event=>{if(event.target.dataset.roleDelete)return;const role=roles.find(value=>value.id===row.dataset.roleId),form=$('#roleForm');form.elements.id.value=role.id;form.elements.name.value=role.name;form.elements.baseRole.value=role.baseRole;permissionCatalog.forEach(permission=>form.elements[`permission_${permission.value}`].checked=role.permissions.includes(permission.value));$('#roleError').textContent=''});document.querySelectorAll('[data-role-delete]').forEach(button=>button.onclick=async event=>{event.stopPropagation();if(!await confirmAction('Rolle wirklich löschen?'))return;try{await json(`/api/roles/${button.dataset.roleDelete}`,{method:'DELETE'});await loadRoles()}catch(e){$('#roleError').textContent=e.message}})}
function resetRoleForm(){const form=$('#roleForm');form.reset();form.elements.id.value='';$('#permissionList').innerHTML=permissionCatalog.map(permission=>`<label><input type="checkbox" name="permission_${permission.value}"> ${esc(membershipPermissionLabel(permission.value))}</label>`).join('');setupRolePermissionSearch();$('#roleError').textContent=''}
async function saveRole(event){event.preventDefault();const form=event.target,id=form.elements.id.value,payload={name:form.elements.name.value,baseRole:form.elements.baseRole.value,permissions:permissionCatalog.filter(permission=>form.elements[`permission_${permission.value}`].checked).map(permission=>permission.value)};try{await json(id?`/api/roles/${id}`:'/api/roles',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await loadRoles();resetRoleForm()}catch(e){$('#roleError').textContent=e.message}}
const openEditWithTemplateCompany=openEdit;
