    json('/api/companies/choices').then(choices=>{$('#lcCompanySelect').innerHTML='<option value="">'+tx('ai.a5fb04','Standardfirma (bisherige Zuordnung)')+'</option>'+choices.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');$('#lcCompanySelect').value=selectedId||''}).catch(()=>{});
