        const block=document.createElement('div');block.className='template-help';
        block.innerHTML='<b>'+tx('ah.7ddbbf','Mit einer Mustervorlage beginnen')+'</b><p>'+tx('ah.4eb69f','Dokumenttyp unten auswählen, Muster herunterladen, in Word gestalten und als DOCX wieder hochladen. Platzhalter in doppelten geschweiften Klammern unverändert lassen.')+'</p><a id="downloadTemplateSample" class="button-link">'+tx('ai.877465','Word-Muster herunterladen')+'</a>';
